        children: "import jakarta.enterprise.context.RequestScoped;\n\nimport java.util.Locale;\nimport java.util.Optional;\nimport java.util.Set;\n\n@RequestScoped\npublic class CurrentRequestContext {\n\n    private String correlationId;\n    private String traceParent;\n    private String tenantId;\n    private String userId;\n    private Set<String> roles = Set.of();\n    private Locale locale = Locale.ENGLISH;\n    private String idempotencyKey;\n\n    public void initialize(\n            String correlationId,\n            String traceParent,\n            String tenantId,\n            String userId,\n            Set<String> roles,\n            Locale locale\n    ) {\n        this.correlationId = require(correlationId, \"correlationId\");\n        this.traceParent = traceParent;\n        this.tenantId = require(tenantId, \"tenantId\");\n        this.userId = require(userId, \"userId\");\n        this.roles = Set.copyOf(roles);\n        this.locale = locale == null ? Locale.ENGLISH : locale;\n    }\n\n    public String correlationId() {\n        return require(correlationId, \"correlationId\");\n    }\n\n    public Optional<String> traceParent() {\n        return Optional.ofNullable(traceParent).filter(value -> !value.isBlank());\n    }\n\n    public String tenantId() {\n        return require(tenantId, \"tenantId\");\n    }\n\n    public String userId() {\n        return require(userId, \"userId\");\n    }\n\n    public Set<String> roles() {\n        return roles;\n    }\n\n    public Locale locale() {\n        return locale;\n    }\n\n    public Optional<String> idempotencyKey() {\n        return Optional.ofNullable(idempotencyKey).filter(value -> !value.isBlank());\n    }\n\n    public void setIdempotencyKey(String idempotencyKey) {\n        this.idempotencyKey = idempotencyKey;\n    }\n\n    public boolean hasRole(String role) {\n        return roles.contains(role);\n    }\n\n    public RequestContextSnapshot snapshot() {\n        return new RequestContextSnapshot(\n                correlationId(),\n                traceParent().orElse(null),\n                tenantId(),\n                userId(),\n                roles(),\n                locale(),\n                idempotencyKey()\n        );\n    }\n\n    private static String require(String value, String name) {\n        if (value == null || value.isBlank()) {\n            throw new IllegalStateException(\"Request context missing: \" + name);\n        }\n        return value;\n    }\n}\n"
