        className: "language-java",
        children: "@ApplicationScoped\npublic class ExternalRuntimeConfigLoader {\n\n    private final ExternalConfigSource externalConfigSource;\n    private final AtomicReference<ExternalRuntimeConfig> current =\n            new AtomicReference<>();\n\n    @PostConstruct\n    public void loadInitial() {\n        current.set(loadAndValidate());\n    }\n\n    public ExternalRuntimeConfig current() {\n        return current.get();\n    }\n\n    public void reload() {\n        ExternalRuntimeConfig next = loadAndValidate();\n        current.set(next);\n    }\n\n    private ExternalRuntimeConfig loadAndValidate() {\n        boolean paymentEnabled = bool(\"payment.enabled\", false);\n        Duration paymentTimeout = duration(\"payment.timeoutMs\", 2_000, 100, 10_000);\n        int maxConcurrentRequests = intRange(\"limits.maxConcurrentRequests\", 100, 1, 10_000);\n\n        return new ExternalRuntimeConfig(\n                paymentEnabled,\n                paymentTimeout,\n                maxConcurrentRequests,\n                Instant.now(),\n                version()\n        );\n    }\n\n    private boolean bool(String key, boolean fallback) {\n        return externalConfigSource.get(key)\n                .map(Boolean::parseBoolean)\n                .orElse(fallback);\n    }\n\n    private Duration duration(String key, long fallback, long min, long max) {\n        long value = externalConfigSource.get(key)\n                .map(Long::parseLong)\n                .orElse(fallback);\n\n        if (value < min || value > max) {\n            throw new InvalidConfigException(key, \"out of range\");\n        }\n\n        return Duration.ofMillis(value);\n    }\n\n    private int intRange(String key, int fallback, int min, int max) {\n        int value = externalConfigSource.get(key)\n                .map(Integer::parseInt)\n                .orElse(fallback);\n\n        if (value < min || value > max) {\n            throw new InvalidConfigException(key, \"out of range\");\n